DROP TABLE IF EXISTS `sys_tenant`;
CREATE TABLE `sys_tenant`  (
  `ID` bigint(20) NOT NULL COMMENT '主键',
  `CREATOR` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '创建人',
  `CREATE_TIME` datetime(0) NOT NULL COMMENT '创建时间',
  `MODIFIER` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '修改人',
  `MODIFY_TIME` datetime(0) NOT NULL COMMENT '修改时间',
  `LOGIC_DEL` tinyint(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `REC_VER` bigint(20) NOT NULL COMMENT '版本号',
  `BUILD_IN` tinyint(1) NULL DEFAULT 0 COMMENT '系统内置（0-否 1-是）',
  `TENANT_ID` bigint(20) NULL DEFAULT NULL COMMENT '租户ID',
  `CODE` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '租户编码',
  `NAME` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '租户名称',
  `TYPE` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '租户类型',
  `STATUS` tinyint(1) NULL DEFAULT 1 COMMENT '租户状态（0-禁用 1-开启）',
  `REMARK` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '租户备注',
  `CONTACT_NAME` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '联系人姓名',
  `CONTACT_TEL` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '联系人电话',
  `CONTACT_EMAIL` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '联系人邮箱',
  `ADDRESS` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '租户地址',
  `BUSINESS_HOURS_FROM` datetime(0) NULL DEFAULT NULL COMMENT '营业时间（从）',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '租户信息表' ROW_FORMAT = Dynamic;

