  INDEX `ID_5`(`ID`) USING BTREE,
  INDEX `ID_6`(`ID`) USING BTREE,
  INDEX `ID_7`(`ID`) USING BTREE,
  CONSTRAINT `FKngr12v76na33eij0xstl6whas` FOREIGN KEY (`DEPT_ID`) REFERENCES `sys_dept` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
