-- ----------------------------
-- Table structure for url_config
-- ----------------------------
DROP TABLE IF EXISTS `url_config`;
CREATE TABLE `url_config`  (
  `ID` bigint(20) NOT NULL COMMENT '主键',
  `CREATOR` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '创建人',
  `CREATE_TIME` datetime(0) NOT NULL COMMENT '创建时间',
  `MODIFIER` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '修改人',
  `MODIFY_TIME` datetime(0) NOT NULL COMMENT '修改时间',
  `LOGIC_DEL` tinyint(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `REC_VER` bigint(20) NOT NULL COMMENT '版本号',
  `BUILD_IN` tinyint(1) NULL DEFAULT 0 COMMENT '系统内置（0-否 1-是）',
  `TENANT_ID` bigint(20) NULL DEFAULT NULL COMMENT '租户ID',
  `CODE` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配置标识',
  `URL` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '网址',
  `REQUEST_TYPE` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '请求方式',
  `HEADER` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '请求头信息',
  `PARAM` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '请求参数',
  `CONTENT_TYPE` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '内容类型',
  `REMARK` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UNIQ_CODE`(`CODE`) USING BTREE COMMENT '配置标识唯一'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'URL配置信息表' ROW_FORMAT = Dynamic;

